def smooth(batch, size):
    pad = size//2
    padded = np.pad(batch, ((0,0), (pad,pad), (pad,pad)), mode='edge')
    return sum(padded[:, i:i+16, j:j+16] for i in range(size) for j in range(size))/(size*size)
candidates = [1, 3, 5]
scores = {size: np.mean((smooth(noisy[validation_ids], size)-clean)**2) for size in candidates}
best_size = min(scores, key=scores.get)
assert best_size in candidates
print('MSE на выборе:', {k: round(v, 4) for k,v in scores.items()})
print('Выбрано окно:', best_size)
